export const bookGrammar: Record<string, Record<string, GrammarNote[]>> = {"a-aki":{"simplified":[{"example":"たくさん書いてありました","tip":"Used with transitive verbs to focus on the result of someone's action rather than who did it.","meaning":"Indicates a state that remains as the result of a conscious action.","pattern":"～てある / ～てあります","jlpt":"N5"},{"pattern":"～と (conditional)","tip":"Use this for natural laws, machines (pushing buttons), or fixed sequences of events.","meaning":"When A occurs, B naturally or inevitably follows.","example":"秋になると","jlpt":"N5"},{"pattern":"～そうです (hearsay)","meaning":"Indicates that the information was heard or read from another source (hearsay).","tip":"Unlike 'looks like' (sou desu), the hearsay version always follows the dictionary form (plain form).","example":"透けて見えるそうです","jlpt":"N4"},{"tip":"Using 'ni omou' often suggests an emotional reaction or a subjective perspective.","meaning":"To feel or think a certain way instinctively.","example":"可哀想に思いました","pattern":"～に思う / ～とおもう","jlpt":"N4"},{"jlpt":"N3","meaning":"While a certain state or condition continues.","tip":"Often implies that if you don't do it now, the chance will disappear (e.g., while it's still summer).","example":"夏のうちはにできています","pattern":"～うちに"},{"jlpt":"N4","pattern":"～よう (Volitional form)","example":"夏休みに海へ行こう","tip":"With Group 2 verbs (ru-verbs), replace 'ru' with 'you'. With Group 1 (u-verbs), change the 'u' sound to 'o' and add 'u'.","meaning":"The 'let's' form, used to express intent or an invitation."},{"example":"話しているのを見ると","tip":"Use 'no' instead of 'koto' when the following verb involves direct perception like seeing, hearing, or waiting.","meaning":"Normalizing a verb to turn an action into a noun/object.","pattern":"～の (Nominalizer)","jlpt":"N4"},{"jlpt":"N3","pattern":"～ようです","example":"書いたようです","tip":"It suggests a logical guess based on evidence, similar to 'it seems that' or 'it looks as if'.","meaning":"Expresses a conjecture or appearance based on what the speaker has observed."}],"intermediate":[{"example":"詩材の準備をしておくのである。","pattern":"～ておく","tip":"Focus on the preparation aspect; it means doing something now so you are ready for later.","meaning":"To do something in advance or for future use.","jlpt":"N4"},{"tip":"For verbs, change the final 'u' sound to 'e' and add 'ba'. It often expresses a logical result.","meaning":"Conditional \"if\" or \"when\".","jlpt":"N4","example":"「秋について」という注文が来れば","pattern":"～ば"},{"meaning":"It seems that... / I heard that... (indicating an inference based on evidence).","tip":"Use this when you have some basis for your guess but aren't 100% certain.","jlpt":"N4","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っているらしい。"},{"tip":"It is used to describe the degree of a state or emotion by providing an example.","meaning":"To the extent that... / So much so that...","jlpt":"N3","example":"私は胸が焼け焦げるほどに、そのみじめな女を恋した。","pattern":"～ほど"},{"pattern":"～と (conditional)","example":"耳を澄まして注意していると","jlpt":"N4","meaning":"When/if (followed by a natural or inevitable consequence).","tip":"In this context, it marks the discovery of something that happens naturally when you take an action."},{"meaning":"Despite / Although / Even though (often used at the end of a sentence to show regret or frustration).","tip":"When it ends a sentence, it often implies \"I wish it weren't so\" or \"despite the situation.\"","jlpt":"N3","pattern":"～のに","example":"もう秋が夏と一緒に忍び込んで来ているのに。"},{"pattern":"～ともなれば","example":"本職の詩人ともなれば、いつどんな注文があるかわからない。","jlpt":"N1","meaning":"When it comes to being... / If someone becomes a... (emphasizes a special status or rank).","tip":"This is used for high-level positions or significant situations where expectations naturally change."}],"original":[{"meaning":"to do something in advance for future use or to leave something in a certain state.","tip":"In speech, this often contracts: ～ておく becomes ～とく.","jlpt":"N4","pattern":"～ておく (～て置く)","example":"準備をして置くのである。"},{"meaning":"indicates a guess based on observation or information; 'it seems like' or 'apparently'.","jlpt":"N4","tip":"Unlike 'yoda', 'rashii' is used when you have some objective basis or rumors for your conclusion.","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っている言葉らしい。"},{"pattern":"～ぬ (～ず)","example":"それを見破ることが出来ぬ。","meaning":"A literary or formal negative form of a verb, equivalent to ～ない.","tip":"You will see this often in literature or proverbs. 'Surnu' becomes 'senu' and 'kuru' becomes 'konu'.","jlpt":"N3"},{"meaning":"emphasizes that once a certain high level or special status is reached, things naturally change or become serious.","tip":"Used for roles, occupations, or special occasions to show a higher standard of expectation.","jlpt":"N1","pattern":"～ともなれば / ～ともなると","example":"本職の詩人ともなれば、いつどんな注文があるか..."},{"pattern":"～ほど (～ほどに)","example":"胸が焼き焦げるほどにそのみじめな女を恋した。","meaning":"indicates the degree or extent of an action or state; 'to the extent that...'.","jlpt":"N3","tip":"Use this to add drama or emphasis to your descriptions by comparing them to an extreme limit."},{"meaning":"indicates an expectation or belief that something should be/have been a certain way, often followed by regret or surprise when it isn't.","jlpt":"N3","tip":"If followed by 'noni', it strongly implies that the reality is the opposite of the expectation.","pattern":"～はず (～筈)","example":"弱者の友であった筈なのに。"},{"meaning":"A formal/literary way to express reason or cause; 'because' or 'due to'.","tip":"This is very stiff and formal. In modern conversation, you would use 'node' or 'kara'. Shortened to 'yue' in some expressions.","jlpt":"N2","pattern":"～がゆえに (～が故に)","example":"並ハズレテ、タクマシキガ故ニ、死ナズ在リヌル。决シテ、ハカナキ態ニハ非ズ。と書かれてある。"}]}};
